125: fn verify_feed_signature(raw: &[u8], sig_b64: &str) -> bool {
126:     use ed25519_dalek::{Signature, Verifier, VerifyingKey};
127:     use base64::Engine;
128:     let pub_bytes = match hex::decode(NEWS_PUBKEY_HEX) {
129:         Ok(b) if b.len() == 32 => b,
130:         _ => return false, // henüz pubkey gömülmedi → duyuru sistemi kapalı
131:     };
132:     let Ok(vk_array) = <[u8; 32]>::try_from(pub_bytes.as_slice()) else { return false };
133:     let Ok(vk) = VerifyingKey::from_bytes(&vk_array) else { return false };
134:     let Ok(sig_bytes) = base64::engine::general_purpose::STANDARD.decode(sig_b64) else { return false };
135:     let Ok(sig_array) = <[u8; 64]>::try_from(sig_bytes.as_slice()) else { return false };
136:     let sig = Signature::from_bytes(&sig_array);
137:     vk.verify(raw, &sig).is_ok()
138: }
