const results = [];
const chunks = [];
for (let i = 0; i < slugs.length; i += 10) chunks.push(slugs.slice(i, i + 10));
for (const chunk of chunks) {
  const r = await Promise.all(chunk.map(async (s) => {
    try {
      const res = await fetch(`https://api.modrinth.com/v2/project/${s}`);
      if (res.ok) {
        const d = await res.json();
        return { slug: s, ok: true, title: d.title, type: d.project_type };
      }
      return { slug: s, ok: false, status: res.status };
    } catch (e) { return { slug: s, ok: false, err: String(e) }; }
  }));
  results.push(...r);
}
const bad = results.filter((x) => !x.ok);
return { total: results.length, ok: results.length - bad.length, bad, types: results.filter((x)=>x.ok && x.type!=="mod").map((x)=>({slug:x.slug,type:x.type})) };

