89: pub fn apply_toggles(inst: &crate::instances::Instance, decisions: &[ModDecision]) -> u32 {
90:     let mods_dir = inst.mods_dir();
91:     let mut done = 0u32;
92:     for d in decisions {
93:         if d.id == "yikimlient" || d.id == "fabric-api" || d.file.is_empty() {
94:             continue;
95:         }
96:         // güvenlik: yalnız mods/ klasörü içindeki .jar dosyalarıyla çalış
97:         let name = std::path::Path::new(&d.file)
98:             .file_name()
99:             .map(|s| s.to_string_lossy().to_string())
100:             .unwrap_or_default();
101:         let active = mods_dir.join(&name);
102:         let disabled = mods_dir.join(format!("{name}.disabled"));
103:         let (from, to) = if d.on {
104:             (disabled, active)
105:         } else {
106:             (active, disabled)
107:         };
108:         if from.exists() {
109:             match std::fs::rename(&from, &to) {
110:                 Ok(()) => done += 1,
111:                 Err(e) => yikim_log(format!("mod toggle başarısız ({name}): {e}")),
112:             }
113:         }
114:     }
115:     done
116: }
