#[tauri::command]
pub async fn cmd_process_restart_request(app: AppHandle) -> Result<Option<crate::curtain::CurtainPlan>, String> {
    use serde_json::json;
    // perde penceresi yüklenene kadar bir an bekle (ilk event'leri kaçırmasin)
    tokio::time::sleep(std::time::Duration::from_millis(700)).await;

    let mut raw_requests: Vec<(crate::instances::Instance, crate::curtain::RestartRequest)> = Vec::new();
    let dir = crate::core::instances_dir();
    if let Ok(entries) = std::fs::read_dir(&dir) {
        for entry in entries.flatten() {
            let inst_dir = entry.path();
            let req = inst_dir.join(".yikim").join("restart-request.json");
            if !req.is_file() { continue; }
            let Ok(content) = std::fs::read_to_string(&req) else { continue };
            let Ok(parsed) = serde_json::from_str::<crate::curtain::RestartRequest>(&content) else {
                let _ = std::fs::remove_file(&req);
                continue;
            };
            let instance_id = if parsed.instance.is_empty() {
                entry.file_name().to_string_lossy().to_string()
            } else { parsed.instance.clone() };
            if let Some(inst) = crate::instances::Instance::load(&instance_id) {
                raw_requests.push((inst, parsed));
            }
            let _ = std::fs::remove_file(&req); // tek kullanımlık
        }
    }

    let Some((inst, request)) = raw_requests.first() else { return Ok(None); };
    let inst = inst.clone();

    // 1) mod aç/kapat — her mod için perdeye canlı event
    let mut toggles = 0u32;
    for d in &request.mods {
        if d.id == "yikimlient" || d.id == "fabric-api" || d.file.is_empty() {
            continue; // çekirdek modlar asla kapatılmaz
        }
        let _ = app.emit("curtain-status", &json!({
            "phase": "toggle", "state": "start", "id": d.id, "file": d.file, "on": d.on
        }));
        match crate::curtain::toggle_one(&inst, d) {
            Ok(true) => {
                toggles += 1;
                let _ = app.emit("curtain-status", &json!({
                    "phase": "toggle", "state": "done", "id": d.id, "file": d.file, "on": d.on, "ok": true
                }));
            }
            Ok(false) => {
                let _ = app.emit("curtain-status", &json!({
                    "phase": "toggle", "state": "done", "id": d.id, "file": d.file, "on": d.on,
                    "ok": false, "note": "bulunamadı"
                }));
            }
            Err(e) => {
                core::yikim_log(format!("mod toggle başarısız ({}): {e}", d.file));
                let _ = app.emit("curtain-status", &json!({
                    "phase": "toggle", "state": "done", "id": d.id, "file": d.file, "on": d.on,
                    "ok": false, "note": "hata"
                }));
            }
        }
    }

    // 2) katalog kurulumları (oyun içi "kur" istekleri) — her biri canlı event
    let mut installed = 0u32;
    for install in &request.installs {
        let _ = app.emit("curtain-status", &json!({
            "phase": "install", "state": "start", "id": install.id, "name": install.name.clone().unwrap_or_else(|| install.id.clone())
        }));
        match repos::install_mod_into(&app, &install.source, &install.id, None, &inst, &inst.mods_dir()).await {
            Ok(_) => {
                installed += 1;
                let _ = app.emit("curtain-status", &json!({
                    "phase": "install", "state": "done", "id": install.id, "ok": true
                }));
            }
            Err(e) => {
                core::yikim_log(format!("oyun içi kurulum başarısızı ({}): {e}", install.id));
                let _ = app.emit("curtain-status", &json!({
                    "phase": "install", "state": "done", "id": install.id, "ok": false, "note": "hata"
                }));
            }
        }
    }

    let plan = crate::curtain::CurtainPlan {
        instance_id: inst.id.clone(),
        toggles,
        installs: installed,
    };
    let _ = app.emit("curtain-status", &json!({
        "phase": "applied", "instance_id": inst.id, "toggles": toggles, "installs": installed
    }));
    core::yikim_log(format!(
        "oyun içi değişiklikler uygulandı: {} toggle, {} kurulum ({})",
        toggles, installed, inst.name
    ));
    Ok(Some(plan))
}
