/// Mod aç/kapat kararlarını uygula: `.jar` ↔ `.jar.disabled` yeniden adlandırma.
/// YIKIM'ın kendi jar'ı ve fabric-api asla kapatılmaz (mod tarafı da bunu garantiler).
pub fn apply_toggles(inst: &crate::instances::Instance, decisions: &[ModDecision]) -> u32 {
    let mods_dir = inst.mods_dir();
    let mut done = 0u32;
    for d in decisions {
        if d.id == "yikimlient" || d.id == "fabric-api" || d.file.is_empty() {
            continue;
        }
        // güvenlik: yalnız mods/ klasörü içindeki .jar dosyalarıyla çalış
        let name = std::path::Path::new(&d.file)
            .file_name()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_default();
        let active = mods_dir.join(&name);
        let disabled = mods_dir.join(format!("{name}.disabled"));
        let (from, to) = if d.on {
            (disabled, active)
        } else {
            (active, disabled)
        };
        if from.exists() {
            match std::fs::rename(&from, &to) {
                Ok(()) => done += 1,
                Err(e) => yikim_log(format!("mod toggle başarısız ({name}): {e}")),
            }
        }
    }
    done
}

/// Perde planını üret ve dosyayı sil (tek kullanımlık istek).
pub fn consume_restart_request() -> Option<CurtainPlan> {
    let dir = instances_dir();
    // restart isteği instance bazlı: tüm kurulumların .yikim klasörüne bak
    let mut plan: Option<CurtainPlan> = None;
    if let Ok(entries) = std::fs::read_dir(&dir) {
        for entry in entries.flatten() {
            let inst_dir = entry.path();
            let req = inst_dir.join(".yikim").join("restart-request.json");
            if !req.is_file() {
                continue;
            }
            let content = match std::fs::read_to_string(&req) {
                Ok(c) => c,
                Err(_) => continue,
            };
            let Ok(parsed) = serde_json::from_str::<RestartRequest>(&content) else {
                let _ = std::fs::remove_file(&req); // bozuk istek de silinsin
                continue;
            };
            let instance_id = if parsed.instance.is_empty() {
                entry.file_name().to_string_lossy().to_string()
            } else {
                parsed.instance.clone()
            };
            plan = Some(CurtainPlan {
                instance_id: instance_id.clone(),
                toggles: parsed.mods.len() as u32,
                installs: parsed.installs.len() as u32,
            });
            // isteği hemen sil (tek kullanımlık)
            let _ = std::fs::remove_file(&req);
            break; // aynı anda tek oturum desteklenir
        }
    }
    plan
}

