/// Perdeyi başlat: tüm ekranı kaplayan dekorasyonsuz pencere aç.
#[tauri::command]
pub async fn cmd_curtain_start(app: AppHandle, instance_id: String, label: String) -> Result<(), String> {
    use tauri::{WebviewUrl, WebviewWindowBuilder};
    if app.get_webview_window("curtain").is_some() {
        return Ok(());
    }
    // son oturum ready dosyasını temizle (yeni oturum için)
    if let Some(inst) = crate::instances::Instance::load(&instance_id) {
        let _ = std::fs::remove_file(crate::curtain::ready_path(&inst));
    }
    let _ = WebviewWindowBuilder::new(
        &app,
        "curtain",
        WebviewUrl::App(format!("curtain.html?instance={instance_id}").into()),
    )
    .title("YIKIMLient")
    .fullscreen(true)
    .decorations(false)
    .resizable(false)
    .focused(true)
    .always_on_top(true)
    .build()
    .map_err(|e| format!("perde penceresi açılamadı: {e}"))?;
    let _ = app.emit("curtain-status", &serde_json::json!({ "phase": "started", "label": label }));
    Ok(())
}

/// Perdeyi kapat (oyun hazır olduğunda frontend bu komutu çağırır).
#[tauri::command]
pub async fn cmd_curtain_ready(app: AppHandle) -> Result<(), String> {
    use tauri::Manager;
    if let Some(win) = app.get_webview_window("curtain") {
        let _ = win.close();
    }
    let _ = app.emit("curtain-status", &serde_json::json!({ "phase": "closed" }));
    Ok(())
}

