/// Perde penceresinin hazır dosyası yoklaması: instance'ın .yikim/ready dosyası
/// var mı (mod ana menüyü çizince yazar). instance_id boş gelirse (URL query
/// kayıpsa) herhangi bir kurulumun ready dosyasına bakılır — perde kilitlenmesin.
#[tauri::command]
pub async fn cmd_check_game_ready(instance_id: String) -> Result<bool, String> {
    if instance_id.is_empty() {
        let dir = crate::core::instances_dir();
        if let Ok(entries) = std::fs::read_dir(&dir) {
            for entry in entries.flatten() {
                if entry.path().join(".yikim").join("ready").is_file() {
                    return Ok(true);
                }
            }
        }
        return Ok(false);
    }
    let Some(inst) = crate::instances::Instance::load(&instance_id) else {
        return Ok(false);
    };
    Ok(crate::curtain::ready_path(&inst).is_file())
}

