25: /// manifest.json'daki tek satır.
26: #[derive(serde::Deserialize)]
27: struct ManifestEntry {
28:     #[serde(rename = "mcVersion")]
29:     mc_version: String,
30:     file: String,
31: }
32: 
33: /// Jar'ın mods listesindeki görüntüsü — Modrinth'te olmadığı için veri URI'si.
34: /// Turuncu zemin üzerinde beyaz Y (marka diline uygun, temadan bağımsız).
35: pub const YIKIM_ICON_DATA_URI: &str = "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><rect width='24' height='24' rx='6' fill='%23ff7a18'/><text x='12' y='16.5' font-family='Segoe UI,system-ui,sans-serif' font-size='13.5' font-weight='700' fill='white' text-anchor='middle'>Y</text></svg>";
36: 
37: /// Gömülü mods dizinini bul. Kurulu pakette tauri `resources` önekini korur
38: /// (`<exe>/resources/mods`), geliştirmede cargo manifest dizini geçerlidir.
39: fn embedded_mods_dir(app: &tauri::AppHandle) -> Option<PathBuf> {
40:     let mut candidates: Vec<PathBuf> = Vec::new();
41:     if let Ok(rd) = app.path().resource_dir() {
42:         candidates.push(rd.join("resources").join("mods"));
43:         candidates.push(rd.join("mods"));
44:     }
45:     candidates.push(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("resources").join("mods"));
46:     candidates.into_iter().find(|d| d.join("manifest.json").is_file())
47: }
48: 
49: fn load_manifest(dir: &Path) -> Option<Vec<ManifestEntry>> {
50:     let text = fs::read_to_string(dir.join("manifest.json")).ok()?;
51:     let js: serde_json::Value = serde_json::from_str(&text).ok()?;
52:     let arr = js["mods"].as_array()?;
53:     let mut out = Vec::new();
54:     for m in arr {
55:         let mc = m["mcVersion"].as_str()?.to_string();
56:         let file = m["file"].as_str()?.to_string();
57:         out.push(ManifestEntry { mc_version: mc, file });
58:     }
59:     if out.is_empty() { None } else { Some(out) }
60: }
61: 
62: /// "1.21.11" → (1, 21, 11); "1.21" → (1, 21, 0); beklenmedik biçimde None.
63: fn parse_version(v: &str) -> Option<(u32, u32, u32)> {
64:     let p: Vec<u32> = v
65:         .split('.')
66:         .map(|s| s.trim().parse::<u32>().ok())
67:         .collect::<Option<_>>()?;
68:     match p.len() {
69:         3 => Some((p[0], p[1], p[2])),
70:         2 => Some((p[0], p[1], 0)),
71:         _ => None,
72:     }
73: }
74: 
75: /// Hedef sürüm için en uygun jar dosyası.
76: fn pick_jar_for(mc_version: &str, dir: &Path) -> Option<PathBuf> {
77:     let entries = load_manifest(dir)?;
78:     // 1) birebir
79:     if let Some(e) = entries.iter().find(|e| e.mc_version == mc_version) {
80:         let p = dir.join(&e.file);
81:         if p.is_file() { return Some(p); }
82:     }
83:     // 2) aynı major.minor içinde en yakın patch
84:     let (tmaj, tmin, tpat) = parse_version(mc_version)?;
85:     let mut best: Option<((u32, u32, u32), &ManifestEntry)> = None;
86:     for e in &entries {
87:         let (mj, mn, pt) = match parse_version(&e.mc_version) {
88:             Some(v) => v,
89:             None => continue,
90:         };
91:         if (mj, mn) != (tmaj, tmin) { continue; }
92:         let dist = pt.abs_diff(tpat);
93:         let better = match best {
94:             None => true,
95:             Some(((bmj, bmn, bpt), _)) => {
96:                 dist < bpt.abs_diff(tpat)
97:                     || (dist == bpt.abs_diff(tpat) && pt < bpt) // eşitlikte küçük sürüm
98:                     || (mj, mn) != (bmj, bmn)
99:             }
100:         };
101:         if better { best = Some(((mj, mn, pt), e)); }
102:     }
103:     best.map(|(_, e)| dir.join(&e.file)).filter(|p| p.is_file())
104: }
105: 
106: /// Kurulum zaten yapılmış mı? (mods/ altında yikimlient-*.jar var mı)
107: fn already_installed(mods_dir: &Path) -> bool {
108:     mods_dir
109:         .read_dir()
110:         .map(|rd| {
111:             rd.filter_map(|e| e.ok())
112:                 .any(|e| {
113:                     let n = e.file_name().to_string_lossy().to_lowercase();
114:                     n.starts_with("yikimlient-") && n.ends_with(".jar")
115:                 })
116:         })
117:         .unwrap_or(false)
118: }
119: 
120: /// YIKIM çekirdeğini kurulumun mods klasörüne ekle (yoksa).
121: /// Dönüş: gerçekten kopyalandı mı. Hata durumunda Err döner; çağıran yalnız
122: /// loglar — oyun akışı asla bloklanmaz.
123: pub fn ensure_installed(app: &tauri::AppHandle, inst: &Instance) -> Result<bool, String> {
124:     let dir = embedded_mods_dir(app).ok_or("gömülü YIKIM modu bulunamadı (resources/mods)")?;
125:     install_from(&dir, inst)
126: }
127: 
128: /// Çekirdek kurulum: kaynak jar dizini + kurulum → mods klasörüne kopya.
129: /// AppHandle'sız; birim testleri de burayı kullanır.
130: pub fn install_from(embedded_dir: &Path, inst: &Instance) -> Result<bool, String> {
131:     if inst.mod_loader != "fabric" {
132:         return Ok(false); // mod yalnızca Fabric
133:     }
134:     if !inst.mc_version.starts_with("1.21") {
135:         return Ok(false); // jar'lar 1.21 ailesine göredir (26.x ayrı iş)
136:     }
137:     let mods_dir = inst.mods_dir();
138:     fs::create_dir_all(&mods_dir).map_err(|e| format!("mods klasörü açılamadı: {e}"))?;
139:     if already_installed(&mods_dir) {
140:         return Ok(false);
141:     }
142:     let jar = pick_jar_for(&inst.mc_version, embedded_dir)
143:         .ok_or_else(|| format!("{} için YIKIM modu jar'ı yok", inst.mc_version))?;
144:     let file_name = jar
145:         .file_name()
146:         .map(|s| s.to_string_lossy().to_string())
147:         .ok_or("jar dosya adı okunamadı")?;
148:     fs::copy(&jar, mods_dir.join(&file_name))
149:         .map_err(|e| format!("YIKIM modu kopyalanamadı: {e}"))?;
150:     core::yikim_log(format!("YIKIM modu kuruldu: {file_name}"));
151:     Ok(true)
152: }
