/// Kurulum zaten yapılmış mı? (mods/ altında yikimlient-*.jar var mı)
fn already_installed(mods_dir: &Path) -> bool {
    mods_dir
        .read_dir()
        .map(|rd| {
            rd.filter_map(|e| e.ok())
                .any(|e| {
                    let n = e.file_name().to_string_lossy().to_lowercase();
                    n.starts_with("yikimlient-") && n.ends_with(".jar")
                })
        })
        .unwrap_or(false)
}

