pub fn ensure_installed(app: &tauri::AppHandle, inst: &Instance) -> Result<bool, String> {
    let dir = embedded_mods_dir(app).ok_or("gömülü YIKIM modu bulunamadı (resources/mods)")?;
    install_from(&dir, inst)
}

