Şimdi Rust implementasyonu:

**Yeni mod dosyası**: `src-tauri/src/game_options.rs` (ya da core.rs içine? Ayrı dosya daha temiz):
```rust
//! Oyun ayar profili — her başlatmada options.txt'ye yazılır.
//! Performans sözü: sınırsız FPS, VSync kapalı, Türkçe arayüz ve PVP dostu
//! erişilebilirlik (sarsıntılar kapalı). Yalnızca bu anahtarlar dokunulur;
//! kullanıcının diğer ayarları (tuşlar, ses, render mesafesi) korunur.

use std::path::Path;
use crate::core::yikim_log;

/// Her açılışta ZORLANAN ayarlar (key, value).
pub const FORCED_OPTIONS: &[(&str, &str)] = &[
    ("lang", "tr_tr"),                    // oyun dili: Türkçe
    ("maxFps", "260"),                    // 260 = sınırsız (UNLIMITED_FRAMERATE_CUTOFF)
    ("enableVsync", "false"),             // dikey senkron kapalı
    ("guiScale", "2"),                    // arayüz ölçeği
    ("fovEffectScale", "0.0"),            // erişilebilirlik: FOV efektleri kapalı
    ("screenEffectScale", "0.0"),         // erişilebilirlik: sarsıntı efektleri kapalı
    ("damageTiltStrength", "0.0"),        // erişilebilirlik: hasar sarsıntısı kapalı
];

pub fn ensure_profile(game_dir: &Path) {
    let path = game_dir.join("options.txt");
    // oku
    let mut lines: Vec<String> = std::fs::read_to_string(&path)
        .map(|t| t.lines().map(str::to_string).collect())
        .unwrap_or_default();
    let mut changed = 0usize;
    for (key, value) in FORCED_OPTIONS {
        let line = format!("{key}:{value}");
        // varsa güncelle
        let mut found = false;
        for l in lines.iter_mut() {
