    match process_restart(app).await {
        Ok(_) => {
            let _ = app.emit("curtain-status", &serde_json::json!({
                "phase": "relaunching", "instance": view.instance_name
            }));
            match crate::commands::cmd_launch_instance(app.clone(), view.instance_id.clone()).await {
                Ok(_) => {
                    close_curtain(app).await; // perdeyi kapat; plan temizlenir; pencere yine gizlenir
                    yikim_log("restart tamamlandı: oyun yeniden açıldı");
                }
                Err(e) => {
                    yikim_log(format!("oyun yeniden açılamadı: {e}"));
                    let _ = app.emit("curtain-status", &serde_json::json!({
                        "phase": "relaunch-failed", "error": e
                    }));
                    tokio::time::sleep(std::time::Duration::from_secs(5)).await;
                    close_curtain(app).await;
                }
            }
        }
        Err(e) => {
            yikim_log(format!("restart isteği uygulanamadı: {e}"));
            let _ = app.emit("curtain-status", &serde_json::json!({
                "phase": "relaunch-failed", "error": e
            }));
            tokio::time::sleep(std::time::Duration::from_secs(5)).await;
            close_curtain(app).await;
        }
    }
}
