// ---------- Perde (oyun içi mod değişikliği akışı) ----------

/// Oyun kapandı ve oyun içi YIKIM modu bir restart isteği bıraktıysa:
/// ÖZEL PERDEYİ AÇ (fullscreen, YIKIMLient'a özel yükleme menüsü), planı state'e
/// koy (perde penceresi cmd_get_curtain_plan ile çeker) ve frontend'e view dön.
/// İstek yoksa hiçbir pencere açılmaz → None döner (normal kapanış).
#[tauri::command]
pub async fn cmd_restart_curtain_open(
    app: AppHandle,
) -> Result<Option<crate::curtain::CurtainPlanView>, String> {
    use serde_json::json;
    use tauri::{WebviewUrl, WebviewWindowBuilder};
    let Some((instance_id, request)) = crate::curtain::peek_restart_request() else {
        return Ok(None);
    };
    // perde listesi: çekirdek korumalı modlar ve boş dosyalar listede görünmez
    let toggles: Vec<crate::curtain::CurtainToggleView> = request
        .mods
        .iter()
        .filter(|d| d.id != "yikimlient" && d.id != "fabric-api" && !d.file.is_empty())
        .map(|d| crate::curtain::CurtainToggleView {
            id: if d.id.is_empty() {
                d.file.trim_end_matches(".jar").to_string()
            } else {
                d.id.clone()
            },
            file: d.file.clone(),
            on: d.on,
        })
        .collect();
    let installs: Vec<crate::curtain::CurtainInstallView> = request
        .installs
        .iter()
        .map(|i| crate::curtain::CurtainInstallView {
            id: i.id.clone(),
            name: i.name.clone().unwrap_or_else(|| i.id.clone()),
        })
        .collect();
    // uygulanacak iş yoksa perde açma; istek dosyası da temizlenir (tekrar tetiklenmesin)
    if toggles.is_empty() && installs.is_empty() {
        if let Some(inst) = Instance::load(&instance_id) {
            let _ = std::fs::remove_file(crate::curtain::restart_request_path(&inst));
        }
        return Ok(None);
    }
    let instance_name = Instance::load(&instance_id)
        .map(|i| i.name)
        .unwrap_or_else(|| instance_id.clone());
    let view = crate::curtain::CurtainPlanView {
        instance_id: instance_id.clone(),
        instance_name,
        label: "Değişiklikler uygulanıyor".into(),
        toggles,
        installs,
    };
    if let Some(state) = app.try_state::<crate::AppState>() {
        *state.curtain_plan.write().await = Some(view.clone());
    }
    if app.get_webview_window("curtain").is_none() {
        // pencere açılamazsa akış yine sürsün: değişiklikler uygulanır + oyun döner;
        // sadece perde görünmez (ör. WebView kısıtı). Abort yok.
        if let Err(e) = WebviewWindowBuilder::new(
            &app,
            "curtain",
            WebviewUrl::App("curtain.html?restart=1".into()),
        )
        .title("YIKIMLient")
        .fullscreen(true)
        .decorations(false)
        .resizable(false)
        .focused(true)
        .always_on_top(true)
        .build()
        {
            core::yikim_log(format!("perde penceresi açılamadı (akış sürüyor): {e}"));
        }
    }
    let _ = app.emit("curtain-status", &json!({ "phase": "started" }));
    core::yikim_log(format!(
        "restart perdesi açıldı: {} değişiklik, {} kurulum ({instance_id})",
        view.toggles.len(),
        view.installs.len()
    ));
    Ok(Some(view))
}

/// Perde penceresi yüklenince planı çeker (pencere açılış yarışını önler).
#[tauri::command]
pub async fn cmd_get_curtain_plan(
    app: AppHandle,
) -> Result<Option<crate::curtain::CurtainPlanView>, String> {
    if let Some(state) = app.try_state::<crate::AppState>() {
        Ok(state.curtain_plan.read().await.clone())
    } else {
        Ok(None)
    }
}

/// Oyun kapandıktan sonra çağrılır (perde açıldıktan SONRA): restart isteğini
/// uygula. Her mod için perdeye canlı event basar (açılıyor/kapatılıyor/kuruluyor →
/// tamamlandı). Dönen değer: uygulanan değişiklik özeti (yoksa None).
#[tauri::command]
pub async fn cmd_process_restart_request(
    app: AppHandle,
) -> Result<Option<crate::curtain::CurtainPlan>, String> {
    use serde_json::json;
    // perde penceresi webview'i yüklenene kadar bir an tanı (ilk event'leri kaçırmasın)
    tokio::time::sleep(std::time::Duration::from_millis(700)).await;

    let mut raw_requests: Vec<(Instance, crate::curtain::RestartRequest)> = Vec::new();
    let dir = crate::core::instances_dir();
    if let Ok(entries) = std::fs::read_dir(&dir) {
        for entry in entries.flatten() {
            let inst_dir = entry.path();
            let req = inst_dir.join(".yikim").join("restart-request.json");
            if !req.is_file() {
                continue;
            }
            let Ok(content) = std::fs::read_to_string(&req) else { continue };
            let Ok(parsed) = serde_json::from_str::<crate::curtain::RestartRequest>(&content) else {
                let _ = std::fs::remove_file(&req);
                continue;
            };
            let instance_id = if parsed.instance.is_empty() {
                entry.file_name().to_string_lossy().to_string()
            } else {
                parsed.instance.clone()
            };
            if let Some(inst) = Instance::load(&instance_id) {
                raw_requests.push((inst, parsed));
            }
            let _ = std::fs::remove_file(&req); // tek kullanımlık
        }
    }

    let Some((inst, request)) = raw_requests.first() else {
        return Ok(None);
    };
    let inst = inst.clone();

    // 1) mod aç/kapat — tek tek, perde ekranında canlı
    let mut toggles = 0u32;
    for d in &request.mods {
        if d.id == "yikimlient" || d.id == "fabric-api" || d.file.is_empty() {
            continue; // çekirdek modlar asla kapatılmaz
        }
        let _ = app.emit(
            "curtain-status",
            &json!({ "phase": "toggle", "state": "start", "id": d.id, "file": d.file, "on": d.on }),
        );
        match crate::curtain::toggle_one(&inst, d) {
            Ok(true) => {
                toggles += 1;
                let _ = app.emit(
                    "curtain-status",
                    &json!({ "phase": "toggle", "state": "done", "id": d.id, "file": d.file, "on": d.on, "ok": true }),
                );
            }
            Ok(false) => {
                let _ = app.emit(
                    "curtain-status",
                    &json!({ "phase": "toggle", "state": "done", "id": d.id, "file": d.file, "on": d.on,
                             "ok": false, "note": "bulunamadı" }),
                );
            }
            Err(e) => {
                core::yikim_log(format!("mod toggle başarısız ({e})"));
                let _ = app.emit(
                    "curtain-status",
                    &json!({ "phase": "toggle", "state": "done", "id": d.id, "file": d.file, "on": d.on,
                             "ok": false, "note": "hata" }),
                );
            }
        }
    }

    // 2) katalog kurulumları (oyun içi "kur" istekleri) — her biri canlı event
    let mut installed = 0u32;
    for install in &request.installs {
        let _ = app.emit(
            "curtain-status",
            &json!({ "phase": "install", "state": "start", "id": install.id,
                     "name": install.name.clone().unwrap_or_else(|| install.id.clone()) }),
        );
        match repos::install_mod_into(&app, &install.source, &install.id, None, &inst, &inst.mods_dir()).await {
            Ok(_) => {
                installed += 1;
                let _ = app.emit(
                    "curtain-status",
                    &json!({ "phase": "install", "state": "done", "id": install.id, "ok": true }),
                );
            }
            Err(e) => {
                core::yikim_log(format!("oyun içi kurulum başarısız ({}): {e}", install.id));
                let _ = app.emit(
                    "curtain-status",
                    &json!({ "phase": "install", "state": "done", "id": install.id, "ok": false, "note": "hata" }),
                );
            }
        }
    }

    let plan = crate::curtain::CurtainPlan {
        instance_id: inst.id.clone(),
        toggles,
        installs: installed,
    };
    let _ = app.emit(
        "curtain-status",
        &json!({
            "phase": "applied",
            "instance_id": inst.id,
            "toggles": toggles,
            "installs": installed
        }),
    );
    core::yikim_log(format!(
        "oyun içi değişiklikler uygulandı: {} toggle, {} kurulum ({})",
        toggles, installed, inst.name
    ));
    Ok(Some(plan))
}

