// Oyun kapandı: oyun içi YIKIM modundan mod değişikliği isteği geldiyse
// ÖZEL PERDE açılır (hangi modlar açılıp kapandığı canlı gösterilir) ve oyun
// otomatik geri açılır. Normal kapanışta perde yok — launcher sadece tazelenir.
listen("game-exit", async (e: any) => {
  const wasPlaying = launch.activeId;
  launch.activeId = null;
  try {
    const view = await invoke("cmd_restart_curtain_open");
    if (view && view.instance_id) {
      // 1) perde açıldı → değişiklikleri uygula (Rust perdeye canlı event basar)
      await invoke("cmd_process_restart_request");
      // 2) oyunu sessizce geri aç; perde "yeniden açılıyor" gösterir
      launch.activeId = view.instance_id;
      ev.emit("curtain-status", { phase: "relaunching", instance: view.instance_name });
      try {
        await invoke("cmd_launch_instance", { instanceId: view.instance_id });
        // oyun süreci doğdu → perdeyi kaldır, sahne oyunun
        await invoke("cmd_curtain_ready");
        void refreshState(true);
      } catch (err) {
        await ev.emit("curtain-status", { phase: "relaunch-failed", error: String(err) });
        launch.activeId = null;
        void refreshState(true);
      }
      return;
    }
  } catch { /* restart isteği yok/okunamadı → normal akış */ }
  void refreshState(true);
  void wasPlaying;
});

