const win = T.window;
const w = win.getCurrentWindow();
$("#tb-min")?.addEventListener("click", () => w.minimize());
$("#tb-max")?.addEventListener("click", () => w.toggleMaximize());
// Oyun çalışırken X = GİZLE (uygulama hayatta kalır: restart/perde akışı ve
// oyunun yeniden başlatılması buna bağlı). Oyun kapalıyken normal kapat.
const closeOrHide = () => {
  if (launch.activeId) {
    w.hide();
    toast("Launcher gizlendi — oyun kapanınca geri gelecek");
    return;
  }
  w.close();
};
$("#tb-close")?.addEventListener("click", closeOrHide);
// Alt+F4 / görev çubuğu kapatması da aynı kurala düşsün
try {
  w.onCloseRequested((e: any) => {
    if (launch.activeId) {
      e?.preventDefault?.();
      w.hide();
      toast("Launcher gizlendi — oyun kapanınca geri gelecek");
    }
  });
} catch { /* eski API ise boşver */ }

