/// Eski `disabled_mods/` klasörünü tek mekanizmaya taşır: `mods/<ad>.jar.disabled`.
fn migrate_disabled_mods(inst: &Instance) {
    let legacy = inst.dir().join("disabled_mods");
    let Ok(entries) = std::fs::read_dir(&legacy) else { return };
    let mut moved = 0usize;
    for e in entries.flatten() {
        let name = e.file_name().to_string_lossy().to_string();
        if !name.ends_with(".jar") { continue; }
        let target = inst.mods_dir().join(format!("{name}.disabled"));
        if target.exists() { continue; }
        if std::fs::rename(e.path(), &target).is_ok() { moved += 1; }
    }
    if moved > 0 {
        core::yikim_log(format!("{} kapalı mod 'mods/.disabled' düzenine taşındı (oyun içi listede görünür)", moved));
    }
}
