/// Oyun içi mod listesi için ikon manifesti: `.yikim/mod-icons.txt` (dosyaAdı<TAB>url).
/// data: URI'ler atlanır (YIKIM çekirdeği kendi rozetini çizer).
pub async fn write_mod_icons(inst: &Instance) {
    let mut filenames: Vec<String> = Vec::new();
    if let Ok(entries) = std::fs::read_dir(inst.mods_dir()) {
        for e in entries.flatten() {
            let n = e.file_name().to_string_lossy().to_string();
            if n.ends_with(".jar") || n.ends_with(".jar.disabled") {
                filenames.push(n);
            }
        }
    }
    if filenames.is_empty() { return; }
    let icons = repos::resolve_mod_icon_urls(&filenames).await;
    let dir = inst.dir().join(".yikim");
    let _ = std::fs::create_dir_all(&dir);
    let mut out = String::new();
    for (name, url) in &icons {
        if url.starts_with("data:") { continue; }
        out.push_str(name); out.push('\t'); out.push_str(url); out.push('\n');
    }
    let _ = std::fs::write(dir.join("mod-icons.txt"), out);
    if !out.is_empty() { core::yikim_log("mod ikon manifesti yazıldı (.yikim/mod-icons.txt)".into()); }
}
