```java
private static void queueDownload(String key, String url) {
    if (!DOWNLOADING.add(key)) return;
    Thread.startVirtualThread(() -> {
        try {
            if (http == null) http = HttpClient.newHttpClient();
            Path target = fileFor(key, url);
            if (!Files.exists(target)) {
                Files.createDirectories(target.getParent());
                HttpRequest req = HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).GET().build();
                HttpResponse<java.nio.file.Path> res = http.send(req, HttpResponse.BodyHandlers.ofFile(target));
                if (res.statusCode() / 100 != 2) Files.deleteIfExists(target);
            }
        } catch (Throwable ignored) {
        } finally { DOWNLOADING.remove(key); }
    });
}
