package com.yikimlient.client;

import java.io.InputStream;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.minecraft.class_1011;
import net.minecraft.class_1043;
import net.minecraft.class_2960;
import net.minecraft.class_310;
import net.minecraft.class_327;
import net.minecraft.class_332;

/**
 * Oyun içi ikon sistemi.
 *
 * Launcher her başlatmada `.yikim/mod-icons.txt` yazar (dosyaAdı<TAB>url),
 * katalog yanıtı da her satırın 7. kolonunda ikon URL'si taşır. İkonlar ilk
 * kullanımda arka planda `.yikim/icons/` altına iner; render sırasında
 * NativeImage olarak yüklenip TextureManager'a kaydedilir ve sonsuza dek
 * çizilir. İndirme oyunu ASLA bloklamaz; gelene dek harf rozeti görünür.
 */
public final class YikimIcons {
    private static final Map<String, String> URLS = new HashMap<String, String>();
    private static final Map<String, class_2960> TEXTURES = new HashMap<String, class_2960>();
    private static final Set<String> DOWNLOADING = new HashSet<String>();
    private static final Set<String> FAILED = new HashSet<String>();
    private static final long MANIFEST_TTL_MS = 30000L;
    private static HttpClient http;
    private static long manifestAt;

    private YikimIcons() {
    }

    private static Path stateDir() {
        return net.fabricmc.loader.api.FabricLoader.getInstance().getGameDir().resolve(".yikim");
    }

    private static Path iconsDir() {
        return YikimIcons.stateDir().resolve("icons");
    }

    private static synchronized void loadManifest() {
        long now = System.currentTimeMillis();
        if (now - manifestAt < YikimIcons.MANIFEST_TTL_MS && !YikimIcons.URLS.isEmpty()) {
            return;
        }
        manifestAt = now;
        try {
            Path f = YikimIcons.stateDir().resolve("mod-icons.txt");
            if (!Files.isRegularFile(f)) {
                return;
            }
            YikimIcons.URLS.clear();
            for (String line : Files.readAllLines(f)) {
                int tab = line.indexOf('\t');
                if (tab <= 0) continue;
                String url = line.substring(tab + 1).trim();
                if (url.isEmpty() || url.startsWith("data:")) continue;
                YikimIcons.URLS.put(line.substring(0, tab), url);
            }
        }
        catch (Throwable ignored) {
            // manifest bozuksa rozetler gösterilir; oyun etkilenmez
        }
    }

    private static String urlFor(String key, String overrideUrl) {
        if (overrideUrl != null && !overrideUrl.isEmpty() && !overrideUrl.startsWith("data:")) {
            return overrideUrl;
        }
        YikimIcons.loadManifest();
        return YikimIcons.URLS.get(key);
    }

    private static Path cacheFile(String key, String url) {
        String name = Integer.toHexString(url.hashCode()) + "-" + Integer.toHexString(url.length()) + ".png";
        return YikimIcons.iconsDir().resolve(name);
    }

    private static void queueDownload(String key, String url) {
        if (!YikimIcons.DOWNLOADING.add(key)) {
            return;
        }
        Thread.startVirtualThread(() -> {
            try {
                Path target = YikimIcons.cacheFile(key, url);
                if (!Files.exists(target)) {
                    Files.createDirectories(target.getParent());
                    if (YikimIcons.http == null) {
                        YikimIcons.http = HttpClient.newHttpClient();
                    }
                    HttpRequest request = HttpRequest.newBuilder(URI.create(url))
                        .timeout(Duration.ofSeconds(10))
                        .GET()
                        .build();
                    HttpResponse<Path> response = YikimIcons.http.send(request, HttpResponse.BodyHandlers.ofFile(target));
                    if (response.statusCode() / 100 != 2) {
                        Files.deleteIfExists(target);
                    }
                }
            }
            catch (Throwable ignored) {
                // ağ yoksa rozet kalır; sonraki açılışta tekrar denenir
            }
            finally {
                YikimIcons.DOWNLOADING.remove(key);
            }
        });
    }

    /** Render iş parçacığında: PNG'yi yükle, dokuyu kaydet. Hata rozete düşer. */
    private static class_2960 register(String key, String url, Path file) {
        try (InputStream in = Files.newInputStream(file)) {
            class_1011 image = class_1011.method_4309(in);
            class_1043 texture = new class_1043(() -> "yikim-icon", image);
            String safe = key.replaceAll("[^a-z0-9_-]", "-");
            if (safe.length() > 40) {
                safe = safe.substring(0, 40);
            }
            class_2960 id = class_2960.method_43902("yikimlient", "icons/" + Integer.toHexString(key.hashCode()) + "-" + safe);
            class_310.method_1551().method_1531().method_4616(id, texture);
            texture.method_4524();
            YikimIcons.TEXTURES.put(key, id);
            return id;
        }
        catch (Throwable ignored) {
            YikimIcons.FAILED.add(key);
            return null;
        }
    }

    /** İkonu çiz; yoksa indir + harf rozeti göster. YIKIM çekirdeği için rozet: drawBadge. */
    public static void draw(class_332 graphics, class_327 font, String key, String url, String label, int x, int y, int size) {
        class_2960 id = YikimIcons.TEXTURES.get(key);
        if (id == null) {
            String realUrl = YikimIcons.urlFor(key, url);
            if (realUrl == null) {
                YikimIcons.letterBadge(graphics, font, label, x, y, size);
                return;
            }
            if (YikimIcons.FAILED.contains(key)) {
                YikimIcons.letterBadge(graphics, font, label, x, y, size);
                return;
            }
            Path file = YikimIcons.cacheFile(key, realUrl);
            if (Files.isRegularFile(file)) {
                id = YikimIcons.register(key, realUrl, file);
