/// Kurulumda bu standart mod zaten var mı? (jar adı normalize önek eşleşmesi)
fn standard_mod_present(mods_dir: &Path, slug: &str) -> bool {
    let slug_n = normalize(slug);
    if let Ok(rd) = std::fs::read_dir(mods_dir) {
        for e in rd.flatten() {
            let name = e.file_name().to_string_lossy().to_lowercase();
            let base = name.trim_end_matches(".disabled").trim_end_matches(".jar");
            let base_n = normalize(base);
            if base_n.starts_with(&slug_n) || base_n.contains(&slug_n) {
                return true;
            }
        }
    }
    false;
}
fn normalize(s: &str) -> String { s.chars().filter(|c| *c != '-' && *c != '_' && *c != '.').collect::<String>().to_lowercase() }
