  const strip = $("#home-news");
  if (!strip) return;
  try {
    // YALNIZCA geliştiricinin imzalı duyuruları (Minecraft haber akışı kaldırıldı).
    const items: any[] = await invoke("cmd_list_yikim_news");
    strip.innerHTML = "";
