      strip.innerHTML = `<div class="card"><p>Duyuru yok — yenilikler burada belirecek.</p></div>`;
      return;
    }
    items.sort((a: any, b: any) => (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0) || b.date.localeCompare(a.date));
